class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedQueue:
    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, value):
        node = Node(value)
        if self.tail is None:
            self.head = node
        else:
            self.tail.next = node
        self.tail = node

    def dequeue(self):
        if self.head is None:
            raise IndexError('dequeue from empty queue')
        value = self.head.value
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        return value
